<?php
require_once dirname(__DIR__) . '/app/init.php'; $customer = require_customer();
$id = filter_var($_GET['id'] ?? null, FILTER_VALIDATE_INT, ['options'=>['min_range'=>1]]);
$order = $id ? customer_order(db(), (int) $customer['id'], $id) : null;
if (!$order) { http_response_code(404); $pageTitle = 'Order not found'; require dirname(__DIR__) . '/templates/header.php'; echo '<div class="container section"><div class="empty-state"><h1>Order not found.</h1><p>This order is unavailable for your account.</p><a class="button" href="' . e(url('/orders.php')) . '">See your orders</a></div></div>'; require dirname(__DIR__) . '/templates/footer.php'; exit; }
$isConfirmation = $isConfirmation ?? false; $pageTitle = $isConfirmation ? 'Your lovely gesture is on its way' : $order['order_reference'];
$statusLabel = ucwords(str_replace('_', ' ', $order['status'])); $payment = $order['payment']; require dirname(__DIR__) . '/templates/header.php';
?>
<div class="container">
<?php if ($isConfirmation): ?><div class="success-heading"><div class="success-symbol" aria-hidden="true">✓</div><p class="eyebrow">A little joy, officially ordered</p><h1>Thanks for spreading<br>some lovely.</h1><p class="muted">Your order is saved. Your payment was simulated; no money was charged.</p></div><?php else: ?><div class="page-heading"><p class="eyebrow">Your lovely gesture</p><h1>Order details</h1><p class="muted"><a class="text-link" href="<?= e(url('/orders.php')) ?>">← All your orders</a></p></div><?php endif; ?>
<article class="receipt"><header class="receipt-heading"><div><p class="eyebrow">Order reference</p><h2><?= e($order['order_reference']) ?></h2></div><span class="status-badge <?= $order['status'] === 'cancelled' ? 'cancelled' : '' ?>"><?= e($statusLabel) ?></span></header><p class="field-help">Placed <?= e(date('F j, Y · g:i a', strtotime($order['created_at']))) ?></p>
<?php require dirname(__DIR__) . '/templates/order_progress.php'; ?><table class="receipt-items"><caption class="eyebrow" style="text-align:left;margin-bottom:5px">Your arrangements</caption><thead><tr><th scope="col">Arrangement</th><th scope="col">Quantity</th><th scope="col">Unit price</th><th scope="col">Total</th></tr></thead><tbody><?php foreach ($order['items'] as $item): ?><tr><td><?= e($item['product_name']) ?></td><td><?= e($item['quantity']) ?></td><td><?= e(format_money($item['unit_price'])) ?></td><td><?= e(format_money(money_to_minor($item['unit_price']) * (int) $item['quantity'])) ?></td></tr><?php endforeach; ?></tbody></table>
<div class="review-details"><div><h2><?= $order['fulfillment_method'] === 'delivery' ? 'Delivery' : 'Store pickup' ?> · <?= e($order['scheduled_date']) ?></h2><?php if ($order['fulfillment_method'] === 'delivery'): ?><p><?= e($order['recipient_name']) ?><br><?= e($order['phone'] ?? $order['recipient_phone']) ?><br><?= nl2br(e($order['address'] ?? $order['delivery_address'])) ?></p><?php else: ?><p>Store pickup on your preferred date.<br>Check this order for its preparation status.</p><?php endif; ?></div><div><h2>Gift message</h2><p><?= !empty($order['gift_message']) ? nl2br(e($order['gift_message'])) : 'No gift message added.' ?></p></div></div>
<div class="receipt-totals"><div class="summary-row"><span>Flowers</span><span><?= e(format_money($order['subtotal'])) ?></span></div><div class="summary-row"><span><?= $order['fulfillment_method'] === 'delivery' ? 'Delivery' : 'Pickup' ?> fee</span><span><?= e(format_money($order['fulfillment_fee'])) ?></span></div><div class="summary-row summary-total"><span>Total</span><strong><?= e(format_money($order['total'])) ?></strong></div></div>
<div class="notice info" style="margin-top:30px;margin-bottom:0"><strong><?= ($payment['status'] ?? '') === 'simulated_refunded' ? 'Simulated payment refunded' : 'Simulated payment recorded' ?></strong><br>Demo reference: <?= e($payment['demo_reference'] ?? 'Unavailable') ?><br><?= ($payment['status'] ?? '') === 'simulated_refunded' ? 'This order was cancelled. The refund is simulated; no money was moved.' : 'School demonstration only. No actual payment was collected.' ?></div><div class="payment-actions"><a class="button" href="<?= e(url('/shop.php')) ?>">Find more lovely flowers ↗</a><a class="text-link" href="<?= e(url('/orders.php')) ?>">Your order history</a></div></article></div><?php require dirname(__DIR__) . '/templates/footer.php'; ?>
